from pathlib import Path
p=Path("workspaces/extractor-srs-design/runtime/html-response-parser.js")
s=p.read_text()
marker="function tablesFromHtml(html, limits) {"
assert s.count(marker)==1
scanner=r'''// Scan large enqueue string literals iteratively; never run a regex over a multi-MB literal.
function enqueueStringLiterals(script) {
  const marker = "window.__reactRouterContext.streamController.enqueue";
  const literals = [];
  let from = 0;
  while (from < script.length) {
    const at = script.indexOf(marker, from);
    if (at < 0) break;
    let i = at + marker.length;
    while (i < script.length && /\s/.test(script[i])) i++;
    if (script[i] !== "(") { from = i + 1; continue; }
    i++;
    while (i < script.length && /\s/.test(script[i])) i++;
    if (script[i] !== '"') { from = i + 1; continue; }
    const begin = i++;
    let escaped = false, closed = false;
    for (; i < script.length; i++) {
      const c = script[i];
      if (escaped) { escaped = false; continue; }
      if (c === "\\") { escaped = true; continue; }
      if (c === '"') { closed = true; i++; break; }
    }
    if (!closed) { from = begin + 1; continue; }
    const end = i;
    while (i < script.length && /\s/.test(script[i])) i++;
    if (script[i] !== ")") { from = i + 1; continue; }
    literals.push(script.slice(begin, end));
    from = i + 1;
  }
  return literals;
}
'''
s=s.replace(marker,scanner+marker)
start=s.index("  const calls = ",s.index(marker))
end=s.index("\n",start)
s=s[:start]+s[end+1:]
old='    calls.lastIndex = 0;\n    let call;\n    while ((call = calls.exec(script[1])) !== null) {'
assert s.count(old)==1
s=s.replace(old,'    for (const literal of enqueueStringLiterals(script[1])) {')
assert s.count("JSON.parse(call[1])")==1
s=s.replace("JSON.parse(call[1])","JSON.parse(literal)")
p.write_text(s)
q=Path("workspaces/extractor-srs-design/tests/html-response-parser.test.js")
t=q.read_text()
assert "iterative scanner handles 10 MiB" not in t
t += r'''
test("iterative scanner handles 10 MiB serialized literal", () => {
  const root = sample();
  const large = "Z".repeat(10 * 1024 * 1024);
  root.loaderData["routes/share.$shareId.($action)"].serverResponse.data.linear_conversation[0].message.content.parts=[large];
  const result = parseHtmlResponse(html(root),validated);
